C# Backend Code Execution:


[HttpPost("create-beam-advanced")]


public async Task<IActionResult> CreateBeamAdvanced([FromBody] BeamRequest request)


{


var model = new Tekla.Structures.Model.Model();






// Create beam object


var beam = new Tekla.Structures.Model.Beam();


beam.StartPoint = new Point(request.start_point.x, request.start_point.y, request.start_point.z);


beam.EndPoint = new Point(request.end_point.x, request.end_point.y, request.end_point.z);


beam.Profile.ProfileString = request.profile;  // "W12X50"


beam.Material.MaterialString = request.material; // "A992"


beam.Class = "1";






// Insert into Tekla model


bool success = beam.Insert();


model.CommitChanges();






if (success) {


return Ok(new {


success = true,


id = beam.Identifier.ID,


message = $"Beam created with ID: {beam.Identifier.ID}"


});


}


}
